def markdown_table(rows: list[dict], columns: list[str] | None = None) -> str:
    if not rows and columns is None:
        return ""

    if columns is None:
        if rows:
            columns = list(rows[0].keys())
        else:
            return ""

    def escape(value):
        return str(value).replace("|", "\\|")

    lines = []
    # Header
    header_cells = [f" {col} " for col in columns]
    lines.append("|" + "|".join(header_cells) + "|")

    # Separator
    sep_cells = [" --- " for _ in columns]
    lines.append("|" + "|".join(sep_cells) + "|")

    # Rows
    for row in rows:
        cells = []
        for col in columns:
            if col in row:
                val = escape(row[col])
                cells.append(f" {val} ")
            else:
                cells.append("  ")
        lines.append("|" + "|".join(cells) + "|")

    return "\n".join(lines)
